    [Fact]
    public void Exact_internal_type_and_member_inventory_is_closed()
    {
        Assert.Equal(["AllocationCarrier","AllocationFingerprint","CapacityRequestCanonicalBytes","CapacityRequestFingerprint","FactoryKey","OperationId","OrderedNodeKeys","ParticipantId","Request"],Props(typeof(GraphParticipantPreGrantPlanV2)));
        Assert.Equal(["CanonicalProjection","CoverageHashV2","CurrentFact","ExecutableFingerprint","ExecutablePlan","ExpiresAt","GrantedAt","GrantId","PreGrantPlan","Topology","TopologyFingerprint"],Props(typeof(GraphParticipantBindingPlanEvidenceV2)));
        Assert.True(typeof(GraphParticipantCapacityPlanBuildResultV2).IsAssignableFrom(typeof(GraphParticipantCapacityPlanBuildResultV2.Found)));
        Assert.True(typeof(GraphParticipantCapacityPlanBuildResultV2).IsAssignableFrom(typeof(GraphParticipantCapacityPlanBuildResultV2.Quarantined)));
        var methods=typeof(GraphParticipantCapacityPlanCompilerV2).GetMethods(BindingFlags.Static|BindingFlags.NonPublic).Where(x=>x.Name is "BuildCapacityRequest" or "GrantMatches").ToArray();
        Assert.Equal(2,methods.Length);Assert.Equal(5,methods.Single(x=>x.Name=="BuildCapacityRequest").GetParameters().Length);Assert.Equal(6,methods.Single(x=>x.Name=="GrantMatches").GetParameters().Length);
    }

    [Fact]
    public void Build_rejects_null_authority_inputs_before_semantics()
    {
        Assert.Throws<ArgumentNullException>(()=>GraphParticipantCapacityPlanCompilerV2.BuildCapacityRequest(null!,null!,null!,default,default));
    }

    [Fact]
    public void Build_result_arms_reject_null_or_default_inputs()
    {
        Assert.Throws<ArgumentNullException>(() => new GraphParticipantCapacityPlanBuildResultV2.Found(null!));
        Assert.Throws<ArgumentException>(() => new GraphParticipantCapacityPlanBuildResultV2.Quarantined(default));
    }

    [Fact]
    public void Pregrant_plan_owns_carrier_request_bytes_and_node_keys()
    {
        var session=new SessionAuthorityStampV1(RuntimeGenerationId.Create(),LiveSessionId.Create());
        var authority=ExpectedAuthorityVectorV1.Create(session,[]);var operation=OperationId.Create();var participant=ParticipantId.Create();
        var charge=new CapacityChargeV1(new CapacityDimensionId(1),new CapacityScopeV1(TenantId.Create(),SessionId.Create(),new CapacitySubjectV1.Participant(participant)),1,CapacityPurposeId.Create(),new CapacityChargeWindowV1.NoWindow());
        var request=new CapacityRequestV1(operation,authority,[charge],new MonotonicStampV1(ClockDomainId.Create(),BootId.Create(),1),CapacityPriorityV1.Normal);
        var carrier=new byte[]{1,2,3};var requestBytes=new byte[]{4,5,6};var nodes=new[]{new BoundedAscii("node")};
        var plan=new GraphParticipantPreGrantPlanV2(participant,operation,new("factory"),carrier,Hash256.Compute([1]),nodes,requestBytes,Hash256.Compute([2]),request);
        carrier[0]=9;requestBytes[0]=9;nodes[0]=new("changed");var carrierCopy=plan.AllocationCarrier;var requestCopy=plan.CapacityRequestCanonicalBytes;carrierCopy[0]=8;requestCopy[0]=8;
        Assert.Equal((byte)1,plan.AllocationCarrier[0]);Assert.Equal((byte)4,plan.CapacityRequestCanonicalBytes[0]);Assert.Equal("node",plan.OrderedNodeKeys[0].ToString());
        var found=new GraphParticipantCapacityPlanBuildResultV2.Found(plan);Assert.Same(plan,found.Plan);
    }

    [Fact]
    public void Grant_matching_rejects_position_and_balance_invariant_failures()
    {
        var session=new SessionAuthorityStampV1(RuntimeGenerationId.Create(),LiveSessionId.Create());var authority=ExpectedAuthorityVectorV1.Create(session,[]);var operation=OperationId.Create();var participant=ParticipantId.Create();var charge=new CapacityChargeV1(new CapacityDimensionId(1),new CapacityScopeV1(TenantId.Create(),SessionId.Create(),new CapacitySubjectV1.Participant(participant)),1,CapacityPurposeId.Create(),new CapacityChargeWindowV1.NoWindow());var request=new CapacityRequestV1(operation,authority,[charge],new MonotonicStampV1(ClockDomainId.Create(),BootId.Create(),1),CapacityPriorityV1.Normal);var plan=new GraphParticipantPreGrantPlanV2(participant,operation,new("factory"),[1],Hash256.Compute([1]),[new BoundedAscii("node")],[2],Hash256.Compute([2]),request);var grantId=CapacityGrantIdDerivationV1.Derive(operation);var one=new JournalPositionV1(session,1);var two=new JournalPositionV1(session,2);var validBalance=new CapacityChargeBalanceV1(charge,1,0,1,0,0,0,0,0,0,1,0);var valid=new CapacityGrantSnapshotV1(grantId,operation,authority,one,one,new CapacityGrantExpiryV1.NoExpiry(),CapacityGrantStateV1.Reserved,[validBalance]);Assert.True(GraphParticipantCapacityPlanCompilerV2.GrantMatches(plan,valid,session,one,out _,out _));
