        var equalExpiry=Mutate(expiry:new CapacityGrantExpiryV1.At(request.Deadline));Assert.False(GraphParticipantCapacityPlanCompilerV2.GrantMatches(plan,equalExpiry,session,one,out _,out _));var earlierExpiry=Mutate(expiry:new CapacityGrantExpiryV1.At(new MonotonicStampV1(request.Deadline.ClockDomainId,request.Deadline.BootId,0)));Assert.False(GraphParticipantCapacityPlanCompilerV2.GrantMatches(plan,earlierExpiry,session,one,out _,out _));var incomparableExpiry=Mutate(expiry:new CapacityGrantExpiryV1.At(new MonotonicStampV1(ClockDomainId.Create(),BootId.Create(),2)));Assert.False(GraphParticipantCapacityPlanCompilerV2.GrantMatches(plan,incomparableExpiry,session,one,out _,out _));
        CapacityChargeBalanceV1 B(long normal=1,long reserve=0,long unactivated=1,long active=0,long released=0,long consumed=0,long aged=0,long revoked=0,long unknown=0,long encNormal=1,long encReserve=0,CapacityChargeV1? exactCharge=null)=>new(exactCharge??charge,normal,reserve,unactivated,active,released,consumed,aged,revoked,unknown,encNormal,encReserve);var changedCharge=new CapacityChargeV1(charge.DimensionId,charge.Scope,1,CapacityPurposeId.Create(),charge.Window);foreach(var bad in new[]{B(normal:0),B(reserve:1),B(unactivated:0),B(active:1),B(released:1),B(consumed:1),B(aged:1),B(revoked:1),B(unknown:1),B(encNormal:0),B(encReserve:1),B(exactCharge:changedCharge)})Assert.False(GraphParticipantCapacityPlanCompilerV2.GrantMatches(plan,Mutate(balances:[bad]),session,one,out _,out _));
